import pulp

prob = pulp.LpProblem("ClinicAssignment", pulp.LpMinimize)

Doctors = ['A', 'B', 'C']
Patients = [1, 2, 3]
Time = {1: 2, 2: 3, 3: 2}
Available_hours = {'A': 8, 'B': 6, 'C': 7}

cost = {
    'A': {1: 300, 2: 350, 3: 400},
    'B': {1: 200, 2: 250, 3: 300},
    'C': {1: 250, 2: 300, 3: 350}
}

variables = pulp.LpVariable.dicts("Assign", [(i, j) for i in Doctors for j in Patients], 0, 1, pulp.LpBinary)

prob += pulp.lpSum([cost[i][j] * variables[(i, j)] for i in Doctors for j in Patients])

for j in Patients:
    prob += pulp.lpSum([variables[(i, j)] for i in Doctors]) == 1

for i in Doctors:
    prob += pulp.lpSum([Time[j] * variables[(i, j)] for j in Patients]) <= Available_hours[i]

prob.solve(pulp.PULP_CBC_CMD(msg=0))

print(f"Answer: {round(pulp.value(prob.objective), 2)}")
