import pulp

# Define the problem
prob = pulp.LpProblem("Minimize_Project_Cost", pulp.LpMinimize)

# Task durations and daily rates
task_durations = {1: 5, 2: 10, 3: 7}
daily_rates = {'A': 100, 'B': 150, 'C': 200}

# Skill matrix
skill_matrix = {
    1: {'A': 1, 'B': 0, 'C': 1},
    2: {'A': 0, 'B': 1, 'C': 1},
    3: {'A': 1, 'B': 1, 'C': 0},
}

# Create variables for each task-architect pair where the architect is capable
variables = {}
for task in [1, 2, 3]:
    for arch in ['A', 'B', 'C']:
        if skill_matrix[task][arch] == 1:
            variables[(task, arch)] = pulp.LpVariable(f"x_{task}_{arch}", 0, 1, pulp.LpBinary)

# Add constraints: each task must be assigned to exactly one architect
for task in [1, 2, 3]:
    prob += pulp.lpSum([variables[(task, arch)] for arch in ['A', 'B', 'C'] if skill_matrix[task][arch] == 1]) == 1

# Objective function: minimize total cost
total_cost = pulp.lpSum([task_durations[task] * daily_rates[arch] * variables[(task, arch)]
                         for task in [1, 2, 3]
                         for arch in ['A', 'B', 'C']
                         if skill_matrix[task][arch] == 1])
prob += total_cost

# Add the total cost constraint (though redundant, it's safe)
prob += total_cost <= 3000

# Solve the problem
prob.solve(pulp.PULP_CBC_CMD(msg=0))

# Print the answer
print(f"Answer: {round(pulp.value(prob.objective), 6)}")
